package com.example.discussions.model;
import com.fasterxml.jackson.annotation.JsonIgnore;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity @Table(name="comments") public class Comment {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@Column(nullable=false,columnDefinition="text") public String body;@ManyToOne(optional=false) @JoinColumn(name="author_id") public User author;@ManyToOne(optional=false) @JoinColumn(name="discussion_id") @JsonIgnore public Discussion discussion;@ManyToOne @JoinColumn(name="parent_id") @JsonIgnore public Comment parent;@OneToMany(mappedBy="parent",cascade=CascadeType.ALL) @OrderBy("createdAt ASC") public List<Comment> replies=new ArrayList<>();@Column(name="created_at",nullable=false) public Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false) public Instant updatedAt=Instant.now();}
